// Second confirmation with a code: shows the operation plan and a code generated by the main
// process. The user must TYPE the code (pasting is blocked) to enable the button.
import { h, setChildren } from '../../../../base/browser/dom.js';
import { icon } from '../../../../base/browser/icons.js';
import { formatBytes } from '../../../../base/common/format.js';
import { t, tn } from '../../../../base/common/nls.js';

const normalize = (s) => String(s || '').toUpperCase().replace(/[^A-Z0-9]/g, '');

export class ConfirmationService {
  #open = null;

  /**
   * @param {object} view  result of host.ops.prepare (title, message, items, more, code, danger, confirmLabel…)
   * @param {(code:string)=>Promise<{ok:boolean,error?:string,expired?:boolean}>} onSubmit
   * @returns {Promise<object|null>} the commit result, or null if cancelled
   */
  confirm(view, onSubmit) {
    this.#open?.close(null);
    return new Promise((resolve) => {
      const code = view.code;
      const pretty = code.slice(0, 3) + ' ' + code.slice(3);
      const error = h('p.cm-error', { role: 'alert', hidden: true });
      const input = h('input.cm-input', {
        type: 'text', inputmode: 'text', autocomplete: 'off', spellcheck: false, maxlength: 12,
        'aria-label': t('confirm.inputLabel', { code: pretty }), placeholder: '— — —  — — —',
      });
      const submit = h(`button.btn.${view.danger ? 'btn-danger' : 'btn-primary'}`, { disabled: true }, view.confirmLabel || t('common.confirm'));
      const cancel = h('button.btn.btn-secondary', t('common.cancel'));
      const matches = () => normalize(input.value) === code;

      const update = () => {
        submit.disabled = !matches();
        input.classList.toggle('ok', matches());
        error.hidden = true;
      };
      input.addEventListener('input', update);
      // force reading: the code has to be typed
      for (const ev of ['paste', 'drop']) input.addEventListener(ev, (e) => {
        e.preventDefault();
        error.textContent = t('confirm.pasteDisabled');
        error.hidden = false;
      });

      let busy = false;
      const doSubmit = async () => {
        if (!matches() || busy) return;
        busy = true;
        submit.disabled = true;
        cancel.disabled = true;
        submit.textContent = t('confirm.running');
        const res = await onSubmit(input.value).catch((err) => ({ ok: false, error: String(err?.message || err) }));
        busy = false;
        if (res?.ok) { close(res); return; }
        cancel.disabled = false;
        submit.textContent = view.confirmLabel || t('common.confirm');
        error.textContent = res?.error || t('confirm.failed');
        error.hidden = false;
        if (res?.expired) { submit.disabled = true; input.disabled = true; }
        else { input.select(); update(); error.hidden = false; }
      };

      const items = (view.items || []).map((it) => h('li',
        h('span.cm-item-label', { title: it.label }, it.label),
        h('span.cm-item-detail', { title: it.detail }, it.detail || ''),
        it.size !== undefined ? h('span.cm-item-size', formatBytes(it.size)) : null));

      const dialog = h(`div.cm-dialog${view.danger ? '.danger' : ''}`, { role: 'alertdialog', 'aria-modal': 'true', 'aria-labelledby': 'cm-title', 'aria-describedby': 'cm-msg' },
        h('header.cm-head',
          h('span.cm-icon', { html: icon(view.danger ? 'trash' : 'shield', 20) }),
          h('div',
            h('div.eyebrow', t('confirm.eyebrow')),
            h('h2#cm-title', view.title))),
        h('p#cm-msg.cm-message', view.message),
        items.length ? h('ul.cm-items', items, view.more ? h('li.cm-more', tn('confirm.more', view.more)) : null) : null,
        view.skipped ? h('p.cm-note', tn('confirm.skipped', view.skipped)) : null,
        h('div.cm-code-box',
          h('p.cm-code-label', t('confirm.codeLabel')),
          h('div.cm-code', { 'aria-hidden': 'true' }, [...code].map((c, i) => h(`span${i === 3 ? '.gap' : ''}`, c))),
          input,
          error),
        h('footer.cm-actions', cancel, submit));

      const overlay = h('div.cm-overlay', dialog);
      const onKey = (e) => {
        if (e.key === 'Escape' && !busy) { e.preventDefault(); close(null); }
        else if (e.key === 'Enter' && document.activeElement === input) { e.preventDefault(); doSubmit(); }
        else if (e.key === 'Tab') {
          // keep focus inside the dialog
          const focusables = [...dialog.querySelectorAll('button:not(:disabled), input:not(:disabled)')];
          const first = focusables[0], last = focusables[focusables.length - 1];
          if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
          else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
        }
      };
      const close = (result) => {
        document.removeEventListener('keydown', onKey, true);
        overlay.remove();
        this.#open = null;
        resolve(result);
      };
      submit.addEventListener('click', doSubmit);
      cancel.addEventListener('click', () => close(null));
      overlay.addEventListener('mousedown', (e) => { if (e.target === overlay && !busy) close(null); });
      document.addEventListener('keydown', onKey, true);
      document.body.append(overlay);
      this.#open = { close };
      requestAnimationFrame(() => input.focus());
    });
  }
}
